auto partition_map = std::make_unique<std::map<float, BucketPtr>>();
buckets_out.clear();
buckets_out.reserve(num_buckets);

int total_partitions = num_buckets * partitions_per_bucket;
if (total_partitions == 0) {
    return partition_map;
}

float step = 1.0f / total_partitions;

for (int i = 0; i < num_buckets; ++i) {
    std::vector<float> points;
    points.reserve(partitions_per_bucket);

    // To distribute partitions uniformly across buckets on the unit circle,
    // we assign points such that each bucket's points are interleaved.
    // Bucket i gets points at indices: i, i + num_buckets, i + 2*num_buckets, ...
    for (int j = 0; j < partitions_per_bucket; ++j) {
        float point = (i + j * num_buckets) * step;
        points.push_back(point);
    }

    std::string name = "bucket_" + std::to_string(i);
    auto bucket = std::make_shared<Bucket>(name, std::move(points));
    buckets_out.push_back(bucket);

    for (float p : bucket->partition_points()) {
        (*partition_map)[p] = bucket;
    }
}

return partition_map;

